const cfg = $input.first().json;
const owner = cfg.repo_owner;
const repo = cfg.repo_name;
const days = Number(cfg.days) || 7;
const lang = String(cfg.language || 'en').toLowerCase();
const since = new Date(Date.now() - days * 86400000).toISOString();
const base = 'https://api.github.com/repos/' + owner + '/' + repo;
const headers = { 'User-Agent': 'n8n-claude-weekly-digest', 'Accept': 'application/vnd.github+json' };
if ($env.GITHUB_TOKEN) headers.Authorization = 'Bearer ' + $env.GITHUB_TOKEN;
const get = async (path) => { try { return await this.helpers.httpRequest({ method: 'GET', url: base + path, headers, json: true }); } catch (e) { return []; } };
const commits = await get('/commits?since=' + since + '&per_page=100');
const issues = await get('/issues?state=closed&since=' + since + '&per_page=100');
const prs = await get('/pulls?state=closed&sort=updated&direction=desc&per_page=100');
const closedIssues = (issues || []).filter(i => !i.pull_request);
const mergedPrs = (prs || []).filter(p => p.merged_at && new Date(p.merged_at).toISOString() >= since);
const oneline = (s) => String(s || '').split('\n')[0].slice(0, 80);
const cLine = (c) => '- ' + String(c.sha || '').slice(0, 7) + ' ' + oneline(c.commit && c.commit.message);
const iLine = (i) => '- #' + i.number + ' ' + oneline(i.title);
const pLine = (p) => '- #' + p.number + ' ' + oneline(p.title) + ' (@' + ((p.user && p.user.login) || '?') + ')';
const digest = ['Repo: ' + owner + '/' + repo, 'Window: last ' + days + ' days', 'Commits: ' + commits.length, commits.slice(0, 30).map(cLine).join('\n'), 'Closed issues: ' + closedIssues.length, closedIssues.slice(0, 30).map(iLine).join('\n'), 'Merged PRs: ' + mergedPrs.length, mergedPrs.slice(0, 30).map(pLine).join('\n')].join('\n');
const langLine = lang === 'fr' ? 'Write the summary in French.' : 'Write the summary in English.';
const prompt = 'You are a developer writing a friendly weekly project digest for a team. ' + langLine + ' Turn the raw activity below into a short narrative: highlight shipped work, notable fixes and momentum. Be concrete, use markdown, 150-250 words, invent nothing.\n\n' + digest;
return [{ json: { repo: owner + '/' + repo, language: lang, counts: { commits: commits.length, issues: closedIssues.length, prs: mergedPrs.length }, prompt } }];

const r = $input.first().json;
const text = (r && r.content && r.content[0] && r.content[0].text) ? r.content[0].text : '(no summary produced)';
return [{ json: { summary: text } }];
